assert [l[2]['kind'] for l in _ev] == ['fragments_placed_in_the_ark', 'aaron_buried', 'demand_declared', 'heart_circumcision_commanded', 'stranger_love_commanded', 'cleaving_commanded'] and [l[2].get('placement') for l in _ev[:2]] == ['reading_placed', 'reading_placed'] and [_WN.clock.eras['exodus'].date(l[2]['dated']) for l in _ev[:2]] == [(2, 1, 1), (40, 5, 1)], [(l[2]['kind'], l[2].get('dated'), l[2].get('placement')) for l in _ev]
